 "content": "from collections import Counter


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    singleton_cells = []
    component_sizes = Counter()

    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = g[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and g[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            component_sizes[color] = max(component_sizes[color], len(component))
            if len(component) == 1:
                singleton_cells.append((r, c, color))

    # Isolated colors that have no larger component are corruption marks.
    for r, c, color in singleton_cells:
        if component_sizes[color] > 1:
            continue
        neighbors = [g[y][x]
                     for y in range(max(0, r - 1), min(h, r + 2))
                     for x in range(max(0, c - 1), min(w, c + 2))
                     if (y, x) != (r, c)]
        if neighbors:
            counts = Counter(neighbors)
            best = max(counts.values())
            # Prefer the most common surrounding color; stable tie-break via 4-neighbor counts.
            tied = [v for v, n in counts.items() if n == best]
            if len(tied) > 1:
                orth = Counter(g[y][x] for y, x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                               if 0 <= y < h and 0 <= x < w)
                tied.sort(key=lambda v: (-orth[v], v))
            g[r][c] = tied[0]
    return g
